abstract class SchoolMember { abstract String getDashboard(); } class AdminMember extends SchoolMember { String getDashboard(){return "Students, staff, payments and reports";} } class TeacherMember extends SchoolMember { String getDashboard(){return "Courses, attendance and results";} } class StudentMember extends SchoolMember { String getDashboard(){return "My courses, results and payments";} }
public class SchoolPolymorphismDemo { public static void main(String[] args){SchoolMember[] users={new AdminMember(),new TeacherMember(),new StudentMember()};for(SchoolMember u:users)System.out.println(u.getClass().getSimpleName()+": "+u.getDashboard());} }
